window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8eb3a92b411d67d4"]={"versions": [{"id": "FIG-8eb3a92b411d67d4", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Kommunikationsübersichtsdiagramm für ein verteiltes OBD-System (Distributed On-Board Diagnostics) im Kontext des AUTOSAR Remote Event Communication Protocol (RecM Bus Protocol). Es visualisiert die hierarchische Rollenverteilung und den Kommunikationsfluss zwischen externen Prüfwerkzeugen, Gateways und Steuergeräten (ECUs) zur zentralisierten Sammlung und Verwaltung von OBD-relevanten Diagnoseereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scan Tool</strong>: Externes Diagnosetester-Werkzeug zur Auslesung von OBD-Daten.</li>\n<li><strong>Gateway</strong>: Vermittlungsinstanz, die Diagnoseanfragen vom Scan Tool an das Primärsteuergerät weiterleitet.</li>\n<li><strong>Master or Primary (grün umrandet)</strong>: Zentrales Steuergerät mit der Aufgabe der OBD-konformen Fehlerverwaltung (OBD-compliant error administration). Es empfängt Statusberichte und sendet Steuerbefehle.</li>\n<li><strong>Secondary ECU (orange umrandet)</strong>: Nachgeordnetes Steuergerät zur eigenständigen Ermittlung des Diagnosestatus („Determine diagnostic status“) sowie Zwischenspeicherung und Weiterleitung empfangener Statusmeldungen („Store & forward received status“).</li>\n<li><strong>Extended Dependent Secondary ECU (magenta umrandet)</strong>: Untergeordnetes Steuergerät, optional nicht AUTOSAR-konform („non-AUTOSAR“), das seinen lokalen Diagnosestatus ermittelt („Determine diagnostic status“).</li>\n<li><strong>Nachrichtenbeziehungen</strong>:</li>\n<li><code>Management commands</code>: Gerichtet von Master or Primary an Secondary ECU sowie von Secondary ECU an Extended Dependent Secondary ECU.</li>\n<li><code>Report diagnostic status</code>: Gerichtet von Extended Dependent Secondary ECU an Secondary ECU sowie von Secondary ECU an Master or Primary.</li>\n<li>Diagnoseanbindung: Unidirektionaler Pfad vom Scan Tool über das Gateway zum Master or Primary.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der dynamische Ablauf gliedert sich in zwei Kommunikationsrichtungen:</p>\n<ol class=\"fig-list\">\n<li><strong>Top-Down-Steuerung</strong>: Master or Primary sendet Protokoll- und Diagnose-Steuerungsbefehle (<code>Management commands</code>) kaskadierend an die Secondary ECU, welche diese wiederum an nachgelagerte Extended Dependent Secondary ECUs weiterleitet.</li>\n<li><strong>Bottom-Up-Statusmeldung</strong>: Extended Dependent Secondary ECUs ermitteln ihren internen Diagnosestatus und melden ihn via <code>Report diagnostic status</code> an die Secondary ECU. Die Secondary ECU aggregiert bzw. speichert und leitet diese Statusinformationen zusammen mit ihren eigenen Diagnosedaten an das Master- bzw. Primary-Steuergerät weiter („Store & forward received status“).</li>\n<li><strong>OBD-Auslesung</strong>: Das Scan Tool greift über das Gateway auf das Master-Steuergerät zu, welches die konsolidierten Fehlerinformationen OBD-konform bereitstellt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zentrales Architekturmuster für RecM-fähige Busteilnehmer: Nur das Master- bzw. Primary-Steuergerät muss eine vollständige, OBD-konforme Fehlerschnittstelle für externe Diagnosetester vorhalten. Sekundäre Steuergeräte benötigen lediglich den RecM-Protokollstack zur Berichterstattung („Store & forward“) und Befehlsverarbeitung. Durch die Unterstützung von „non-AUTOSAR“-Knoten ermöglicht das Protokoll die standardisierte Integration proprietärer oder teilspezifischer Steuergeräte in die AUTOSAR-OBD-Fehlerverwaltung.</p>"}, {"id": "FIG-63eda5ab4f04a977", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Kommunikationsübersichtsdiagramm für ein verteiltes OBD-System (Distributed On-Board Diagnostics) im Kontext des AUTOSAR Remote Event Communication Protocol (RecM Bus Protocol). Es visualisiert die hierarchische Rollenverteilung und den Kommunikationsfluss zwischen externen Prüfwerkzeugen, Gateways und Steuergeräten (ECUs) zur zentralisierten Sammlung und Verwaltung von OBD-relevanten Diagnoseereignissen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst folgende Entitäten und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scan Tool</strong>: Externes Diagnosetester-Werkzeug zur Auslesung von OBD-Daten.</li>\n<li><strong>Gateway</strong>: Vermittlungsinstanz, die Diagnoseanfragen vom Scan Tool an das Primärsteuergerät weiterleitet.</li>\n<li><strong>Master or Primary (grün umrandet)</strong>: Zentrales Steuergerät mit der Aufgabe der OBD-konformen Fehlerverwaltung (OBD-compliant error administration). Es empfängt Statusberichte und sendet Steuerbefehle.</li>\n<li><strong>Secondary ECU (orange umrandet)</strong>: Nachgeordnetes Steuergerät zur eigenständigen Ermittlung des Diagnosestatus („Determine diagnostic status“) sowie Zwischenspeicherung und Weiterleitung empfangener Statusmeldungen („Store & forward received status“).</li>\n<li><strong>Extended Dependent Secondary ECU (magenta umrandet)</strong>: Untergeordnetes Steuergerät, optional nicht AUTOSAR-konform („non-AUTOSAR“), das seinen lokalen Diagnosestatus ermittelt („Determine diagnostic status“).</li>\n<li><strong>Nachrichtenbeziehungen</strong>:</li>\n<li><code>Management commands</code>: Gerichtet von Master or Primary an Secondary ECU sowie von Secondary ECU an Extended Dependent Secondary ECU.</li>\n<li><code>Report diagnostic status</code>: Gerichtet von Extended Dependent Secondary ECU an Secondary ECU sowie von Secondary ECU an Master or Primary.</li>\n<li>Diagnoseanbindung: Unidirektionaler Pfad vom Scan Tool über das Gateway zum Master or Primary.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der dynamische Ablauf gliedert sich in zwei Kommunikationsrichtungen:</p>\n<ol class=\"fig-list\">\n<li><strong>Top-Down-Steuerung</strong>: Master or Primary sendet Protokoll- und Diagnose-Steuerungsbefehle (<code>Management commands</code>) kaskadierend an die Secondary ECU, welche diese wiederum an nachgelagerte Extended Dependent Secondary ECUs weiterleitet.</li>\n<li><strong>Bottom-Up-Statusmeldung</strong>: Extended Dependent Secondary ECUs ermitteln ihren internen Diagnosestatus und melden ihn via <code>Report diagnostic status</code> an die Secondary ECU. Die Secondary ECU aggregiert bzw. speichert und leitet diese Statusinformationen zusammen mit ihren eigenen Diagnosedaten an das Master- bzw. Primary-Steuergerät weiter („Store & forward received status“).</li>\n<li><strong>OBD-Auslesung</strong>: Das Scan Tool greift über das Gateway auf das Master-Steuergerät zu, welches die konsolidierten Fehlerinformationen OBD-konform bereitstellt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zentrales Architekturmuster für RecM-fähige Busteilnehmer: Nur das Master- bzw. Primary-Steuergerät muss eine vollständige, OBD-konforme Fehlerschnittstelle für externe Diagnosetester vorhalten. Sekundäre Steuergeräte benötigen lediglich den RecM-Protokollstack zur Berichterstattung („Store & forward“) und Befehlsverarbeitung. Durch die Unterstützung von „non-AUTOSAR“-Knoten ermöglicht das Protokoll die standardisierte Integration proprietärer oder teilspezifischer Steuergeräte in die AUTOSAR-OBD-Fehlerverwaltung.</p>"}], "trans": [{"from": "FIG-8eb3a92b411d67d4", "to": "FIG-63eda5ab4f04a977", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
